// ---------------------------------------------------------
// 최초 소지 아이템 (게임 시작/페이즈 시작 시 이미 소유한 상태로 등록)
// ---------------------------------------------------------

// 1페이즈: 최초 소지 단서 없음
const PHASE1_STARTING_CLAIMS = {};

// CLUES 바깥에 따로 등록하는 단서 (현재 없음)
const STANDALONE_ITEMS = {};

// 2페이즈: 각 캐릭터가 자신의 상자에서 이미 확인한 것으로 간주하는 개인 단서
const PHASE2_STARTING_CLAIMS = {
  "p2-box-jueun-a": "jueun",
  "p2-box-jueun-b": "jueun",
  "p2-box-yuseong-a": "yuseong",
  "p2-box-yuseong-b": "yuseong",
  "p2-box-donggyeong-a": "donggyeong",
  "p2-box-donggyeong-b": "donggyeong",
  "p2-box-saebom-a": "saebom",
  "p2-box-saebom-b": "saebom"
};

// 양도할 수 없는 최초 소지 단서인지 (1페이즈 최초 소지 단서는 없어졌지만, 2페이즈 개인 상자 단서는 여기에 해당)
function isStartingClue(clueId) {
  return Object.prototype.hasOwnProperty.call(PHASE1_STARTING_CLAIMS, clueId) ||
    Object.prototype.hasOwnProperty.call(PHASE2_STARTING_CLAIMS, clueId);
}

// ---------------------------------------------------------
// 잠긴 방 해제 조건 (페이즈 무관, 방 id 기준)
// ---------------------------------------------------------
const ROOM_UNLOCK_CONDITIONS = {
  // 1페이즈 산장주인의 방: <조건 달성 후 열림> — 1페이즈 동안은 열리지 않는다.
  "room-host-p1": () => false,
  // 2페이즈 계단: 산장주인의 방 '숨겨진 통로'(E)가 공개되면 열림 (강제 전체 공개)
  "room-stairs": (revealed) => revealed.has("p2-host-e"),
  // 2페이즈 지하실: 계단 '지하실의 문'(C) 공개 AND 1페이즈 주은의 방 '열쇠'(D) 공개
  // ('지하실의 문'을 획득하면 그 열쇠도 소지자와 관계없이 함께 강제 공개된다)
  "room-basement": (revealed) => revealed.has("p2-stairs-c") && revealed.has("p1-jueun-d"),
  // 3페이즈 지하실: 서재 '통로'(E)가 공개되면 열림 (강제 전체 공개)
  "room-basement-p3": (revealed) => revealed.has("p3-study-e")
};

function isRoomUnlocked(roomId, revealedClueIds) {
  const condition = ROOM_UNLOCK_CONDITIONS[roomId];
  if (!condition) return true; // 조건이 정의되지 않은 방은 항상 열려 있다.
  return condition(new Set(revealedClueIds));
}

// (하위 호환용) 기존 코드에서 쓰던 이름
function isBasementUnlocked(revealedClueIds) {
  return isRoomUnlocked("room-basement", revealedClueIds);
}

// clueId로 CLUES 안의 단서 원본 객체를 찾는다 (forceReveal 등 속성 확인용)
function findClueItem(clueId) {
  for (const phaseKey of Object.keys(CLUES)) {
    for (const room of CLUES[phaseKey].rooms) {
      const item = room.items.find((i) => i.id === clueId);
      if (item) return item;
    }
  }
  return null;
}

// clueId로 라벨/본문/소속 이름을 찾는다 (CLUES 방 아이템 + STANDALONE_ITEMS)
function findClueInfo(clueId) {
  if (STANDALONE_ITEMS[clueId]) return STANDALONE_ITEMS[clueId];
  for (const phaseKey of Object.keys(CLUES)) {
    for (const room of CLUES[phaseKey].rooms) {
      const item = room.items.find((i) => i.id === clueId);
      if (item) return { label: item.label, body: item.body, roomName: room.name };
    }
  }
  return null;
}

